// Extrai a mensagem do lead
const body = $input.item.json.body || $input.item.json;
const entries = body.entry || [];

let leadPhone = null;
let leadName = null;
let messageText = null;
let messageType = null;

for (const entry of entries) {
  for (const change of (entry.changes || [])) {
    const value = change.value || {};
    const contacts = value.contacts || [];
    if (contacts[0]) leadName = contacts[0].profile?.name || null;
    for (const msg of (value.messages || [])) {
      leadPhone = msg.from;
      messageType = msg.type;
      if (msg.type === 'text') messageText = msg.text?.body || '';
      else if (msg.type === 'interactive') messageText = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
      else messageText = `[${msg.type}]`;
    }
  }
}

if (!leadPhone || !messageText) {
  // Não é evento de mensagem (pode ser status update). Ignora.
  return { json: { skip: true } };
}

return {
  json: { leadPhone, leadName, messageText, messageType, skip: false }
};

// Extrai histórico do lead e monta payload pro Claude
const lead = $input.item.json;
const inbound = $('Parse mensagem do lead').item.json;
const props = lead.property || lead.properties || {};

const getText = (key) => {
  const p = props[key];
  if (!p) return '';
  if (p.title) return p.title.map(t => t.plain_text).join('');
  if (p.rich_text) return p.rich_text.map(t => t.plain_text).join('');
  if (p.select) return p.select?.name || '';
  if (p.status) return p.status?.name || '';
  if (p.phone_number) return p.phone_number;
  if (p.url) return p.url;
  return '';
};

const historicoExistente = getText('Histórico');
const now = new Date().toISOString().replace('T', ' ').slice(0, 16);
const novaLinha = `[${now} LEAD] ${inbound.messageText}`;
const historicoAtualizado = historicoExistente ? `${historicoExistente}\n${novaLinha}` : novaLinha;

return {
  json: {
    lead_id: lead.id,
    nome: getText('Nome'),
    empresa: getText('Empresa'),
    cargo: getText('Cargo'),
    whatsapp: getText('WhatsApp'),
    gatilho: getText('Gatilho de prospecção'),
    setor: getText('Setor'),
    instagram: getText('Instagram'),
    site: getText('Site da empresa'),
    ultima_msg_lead: inbound.messageText,
    historico: historicoAtualizado,
    is_first_touch: false
  }
};

